def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if float(opp.get('budget', 0)) >= DAILY_SALARY * 1.2:
                rich_count += 1
            if int(opp.get('no_water_days', 0)) >= 2 or float(opp.get('hp', 0)) <= 4:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass

    if not alive:
        return min(budget, 8.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days == 1:
        urgency += 1
    if hp <= 3:
        urgency += 3
    elif hp <= 6:
        urgency += 2
    elif hp <= 9:
        urgency += 1

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if urgency >= 5:
        base = DAILY_SALARY * 0.95
    elif urgency >= 3:
        base = DAILY_SALARY * 0.78
    elif tight_supply:
        base = DAILY_SALARY * 0.62
    elif loose_supply:
        base = DAILY_SALARY * 0.34
    else:
        base = DAILY_SALARY * 0.48

    if highest_prev > 0:
        if urgency >= 3:
            target = max(base, min(highest_prev + 2.0, DAILY_SALARY * 1.02))
        else:
            if highest_prev >= DAILY_SALARY * 1.4:
                target = min(base, DAILY_SALARY * 0.42)
            elif highest_prev >= DAILY_SALARY * 0.9:
                target = min(max(base, avg_prev * 0.9), DAILY_SALARY * 0.68)
            else:
                target = max(base, highest_prev + 1.5)
    else:
        target = base

    if desperate_count >= 2 and urgency < 3:
        target *= 0.88
    if rich_count >= 2 and (tight_supply or urgency >= 3):
        target *= 1.08
    if day >= 8 and hp > 6 and no_water_days == 0:
        target *= 0.9

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if urgency < 3 and days_left > 0:
        reserve_floor = min(budget * 0.45, days_left * 8.0)

    bid = min(target, budget)
    if budget - bid < reserve_floor and urgency < 3:
        bid = max(0.0, budget - reserve_floor)

    if urgency >= 5:
        bid = max(bid, min(budget, DAILY_SALARY * 0.92))
    elif no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.85))

    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday's bids from previous_trace for immediate reaction.
    prev_bids = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))

    # Identify if any opponent was bidding extremely high (likely budget-abusive / survival-maximizing).
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base willingness: ensure we don't overspend early; scale with our danger.
    danger = 0
    if hp <= 2.0:
        danger += 2
    if no_water_days >= 2:
        danger += 1

    # Supply pressure: with medium supply (15-25), water is not scarce enough to require max bidding.
    # Use a target bid anchored to a fraction of salary.
    # If opponents were bidding huge yesterday, we need to match some of it to avoid losing.
    if highest_prev_bid >= DAILY_SALARY * 1.6:  # ~144
        # Cindy-like behavior: push higher but still cap to protect budget.
        if danger >= 2:
            target = DAILY_SALARY * 0.95
        elif danger == 1:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.6
        # Slightly undercut the highest previous bid to reduce tie risk while saving budget.
        target = min(target, highest_prev_bid * 0.92)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:  # ~81
        if danger >= 2:
            target = DAILY_SALARY * 0.85
        elif danger == 1:
            target = DAILY_SALARY * 0.65
        else:
            target = DAILY_SALARY * 0.55
        target = min(target, highest_prev_bid * 0.85)
    else:
        # Opponents generally not maxing; bid moderately.
        if danger >= 2:
            target = DAILY_SALARY * 0.8
        elif danger == 1:
            target = DAILY_SALARY * 0.6
        else:
            target = DAILY_SALARY * 0.5

    # If supply is at the low end, increase slightly.
    if supply <= float(MIN_SUPPLY) + 0.5:
        target *= 1.08
    elif supply >= float(MAX_SUPPLY) - 0.5:
        target *= 0.95

    # Final cap by budget.
    bid = max(0.0, min(budget, target))

    # Ensure we don't bid trivially when we're in danger.
    if danger >= 2 and bid < DAILY_SALARY * 0.4:
        bid = min(budget, DAILY_SALARY * 0.75)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # If no opponents are alive, bid minimally to save budget.
    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    # Analyze yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # 1. Critical HP: If HP is very low, bid aggressively to survive.
    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 1.25)

    # 2. End Game Strategy: If close to the end, and doing well, try to secure win.
    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp >= 5 and my_budget > DAILY_SALARY * 2:
            return min(my_budget, DAILY_SALARY * 1.1)
        else:
            return min(my_budget, DAILY_SALARY * 1.2)

    # 3. Adapt to opponent's previous bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.9: # Opponents are bidding aggressively
            # If supply is tight, competition is higher.
            # Check if supply is less than what all alive opponents (including self) would need if they all got their requirement
            if current_supply <= WATER_REQ * (num_alive_opponents + 1): # +1 for myself
                return min(my_budget, max(DAILY_SALARY * 1.05, highest_prev_bid + 5))
            else:
                return min(my_budget, max(DAILY_SALARY * 0.95, highest_prev_bid * 1.02))
        else: # Opponents are bidding relatively low or moderate
            return min(my_budget, max(DAILY_SALARY * 0.8, highest_prev_bid + 2))
    else: # 4. Default / No previous bids available (e.g., Day 1 or all opponents died yesterday)
        # Adjust based on supply and number of opponents
        if num_alive_opponents >= 3: # High competition
            if current_supply <= WATER_REQ * (num_alive_opponents + 1): # Tight supply
                return min(my_budget, DAILY_SALARY * 1.05)
            else:
                return min(my_budget, DAILY_SALARY * 0.9)
        else: # Moderate competition (1 or 2 opponents)
            if current_supply <= WATER_REQ * (num_alive_opponents + 1): # Tight supply
                return min(my_budget, DAILY_SALARY * 0.95)
            else:
                return min(my_budget, DAILY_SALARY * 0.8)

    # Fallback bid (should ideally not be reached if logic is exhaustive)
    return min(my_budget, DAILY_SALARY * 0.9)

